"""Geotagged test photos. A tiny real JPEG, with GPS written into it by app.services.geotag_service."""
import base64

from app.services.geotag_service import write_gps

# A real 48x32 grey JPEG (about 651 bytes)
BASE_JPEG = base64.b64decode(
    ""
)


def geotagged_jpeg(latitude: float, longitude: float) -> bytes:
    return write_gps(BASE_JPEG, latitude, longitude)


def untagged_jpeg() -> bytes:
    return BASE_JPEG
